function signalFlips(a, b) {
  const sa = a.toString(2).padStart(31, '0');
  const sb = b.toString(2).padStart(31, '0');
  let flips = 0;
  for (let i = 0; i < 31; i++) if (sa[i] !== sb[i]) flips++;
  return flips;
}

function signalFlips(a, b) {
  let x = a ^ b, flips = 0;
  while (x !== 0) {
    x &= x - 1;
    flips++;
  }
  return flips;
}
